<script>(function(){var meta=@json($meta),groups={temperature:['ambient_temp','chamber_temp','exhaust_temp'],humidity:['ambient_rh','chamber_rh','exhaust_rh'],airflow:['airflow'],fan:['exhaust_fan_speed']},colors={ambient_temp:'#8ea0ba',chamber_temp:'#ef6a59',exhaust_temp:'#eaa42b',ambient_rh:'#8ea0ba',chamber_rh:'#2f6fed',exhaust_rh:'#47b6bd',airflow:'#20a474',exhaust_fan_speed:'#8067d4'};function make(s){var c=new ApexCharts(document.querySelector(s),{chart:{type:'area',height:240,toolbar:{show:false}},series:[],stroke:{curve:'smooth',width:2},fill:{type:'gradient',gradient:{opacityFrom:.22,opacityTo:.02}},dataLabels:{enabled:false},legend:{position:'top',horizontalAlign:'left',fontSize:'11px'},grid:{borderColor:'#edf1f6',strokeDashArray:3},xaxis:{type:'datetime'},tooltip:{x:{format:'dd MMM HH:mm'}},noData:{text:'Loading readings…'}});c.render();return c}var charts={temperature:make('#temperature-chart'),humidity:make('#humidity-chart'),airflow:make('#airflow-chart'),fan:make('#fan-chart')};function load(range){var keys=Object.values(groups).flat();fetch(@json(route('sensors.history',$environment->id))+'?range='+range+'&keys='+keys.join(',')).then(r=>r.json()).then(result=>Object.keys(groups).forEach(group=>{var series=groups[group].filter(k=>result.series?.[k]?.length).map(k=>({name:meta[k].label,data:result.series[k].map(p=>[p.ts,p.value])}));charts[group].updateOptions({colors:groups[group].map(k=>colors[k])});charts[group].updateSeries(series)})).catch(()=>Object.values(charts).forEach(c=>{c.updateOptions({noData:{text:'History temporarily unavailable'}});c.updateSeries([])}))}document.querySelectorAll('#history-range button').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('#history-range button').forEach(b=>b.classList.remove('active'));btn.classList.add('active');load(btn.dataset.range)}));function refresh(){fetch(@json(route('sensors.status',$environment->id))).then(r=>r.ok?r.json():null).then(s=>{if(!s)return;Object.entries(s.telemetry||{}).forEach(([key,item])=>document.querySelectorAll('[data-telemetry="'+key+'"]').forEach(el=>el.textContent=item.value+(meta[key]?.unit||'')));['circulation_fan','heater'].forEach(key=>{var el=document.querySelector('[data-boolean="'+key+'"]),v=s.telemetry?.[key]?.value,on=v===true||v==='true'||v===1;if(el){el.textContent=on?'ON':'OFF';el.classList.toggle('on',on)}});var bar=document.querySelector('[data-fan-bar]');if(bar&&s.telemetry?.exhaust_fan_speed)bar.style.width=s.telemetry.exhaust_fan_speed.value+'%';document.getElementById('connectivity-text').textContent=s.connectivity}).catch(()=>{})}load('24h');setInterval(refresh,30000)})();</script>
